    /*
     * Assign a AdAccount
     * 
     * @param	parentId	UUID
     * @param	assignment 	AdAccount 
     * @return	Campaign
     */
    public Campaign assignAdAccount( UUID parentId, AdAccount assignment ) {
	    LOGGER.info("assigning AdAccount as " + assignment.toString() );

	    Campaign parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( AdAccount.class, assignment.getAdAccountId());

	    // ------------------------------------------
		// assign the AdAccount to the parent entity
		// ------------------------------------------ 
	    parentEntity.setAdAccount( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

